-- Seed: 72 original OneUp questions (9 per dimension). Generated from lib/features/assess/data/question_bank.dart.
-- IDs are deterministic so the app's local fallback and the DB agree.
on conflict (id) do update set text = excluded.text, scale_type = excluded.scale_type,
  reverse_scored = excluded.reverse_scored, sort_order = excluded.sort_order;
